#!/data/data/com.termux/files/usr/bin/bash
# shellcheck disable=2034,2086,2107,2109

# TermuxConf GUI (c) 2026
# Author: Kamil BuriXon Burek
# Version: 1.0.0
#
# Features:
#  - Browse and edit Termux terminal settings in a local web interface.
#  - Manage boolean options, configurable values and keyboard shortcuts.
#  - Visually configure Extra Keys, including labels, macros and popup actions.
#  - Automatically back up configurations and restore previous versions.
#  - Preserve unrelated settings and comments when saving changes.
#
# License: GNU Affero General Public License v3 (AGPL-3.0)
#  - You may use, run, modify and redistribute this software (including commercially).
#  - If you distribute the program or provide network access to a modified version,
#    you must make the full corresponding source code available under AGPL-3.0
#    and preserve license notices.
#  - You may not relicense the code under a proprietary license that removes
#    recipients' AGPL rights.
#  - The program is provided WITHOUT ANY WARRANTY; include the full AGPL-3.0
#    text when distributing or deploying.
#  - For full terms see the official license (GNU AGPL v3).

SCRIPT_AUTHOR="Kamil BuriXon Burek"
SCRIPT_NAME="TermuxConf"
SCRIPT_VERSION="1.0.0"
SCRIPT_LICENSE="AGPLv3"
SCRIPT_YEAR="2026"

LOGO_B64=""
WEBSITE_B64=""
GITHUB_B64=""
LOADING_B64=""

RED=$'\e[1;31m'
GRN=$'\e[1;32m'
YLW=$'\e[1;33m'
BLU=$'\e[1;34m'
RESET=$'\e[0m'
ERR_COLOR="${RED}[ ERR! ]${RESET}:"
DONE_COLOR="${GRN}[ DONE ]${RESET}:"
INFO_COLOR="${YLW}[ INFO ]${RESET}:"

ADDRESS="127.0.0.1"
PORT=""
WRONG=false
HELP=false
ERR_ARG_MSG=""
unset PORT_SET ADDRESS_SET

TMPROOT="${TMPDIR:-/data/data/com.termux/files/usr/tmp}"
WORK="$TMPROOT/termuxconf"
CONFIG="$HOME/.termux/termux.properties"
BACKUP_DIR="$HOME/.termux/termuxconf-backups"
mkdir -p "$WORK/icons" "$HOME/.termux" "$BACKUP_DIR" || { printf '%b\n' "${ERR_COLOR} cannot prepare working directories"; exit 1; }
LOG="$WORK/run-$(date +%y%m%d-%H%M%S).log"

if ! command -v python3 >/dev/null 2>&1; then
	printf '%b\n' "${ERR_COLOR} command python3 not found. Aborting..."
	exit 1
fi

port_available(){
	python3 - "$1" "$2" <<'PY' >/dev/null 2>&1
import socket,sys
s=socket.socket()
s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,0)
try:
	s.bind((sys.argv[1],int(sys.argv[2])))
except OSError:
	sys.exit(1)
finally:
	s.close()
PY
}

find_port(){
	local p n
	for n in {1..100}; do
		p=$((10000 + RANDOM % 10000))
		if port_available "$ADDRESS" "$p"; then
			printf '%s\n' "$p"
			return 0
		fi
	done
	return 1
}

decode_b64_to_file(){
	local b64="$1" out="$2"
	[ -n "$b64" ] || return 1
	printf "%s" "$b64" | python3 -c 'import sys,base64; sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' >"$out" 2>/dev/null || return 1
	return 0
}

until [ $# -eq 0 ]; do
	case "$1" in
		-p|--port)
			if [ -z "${2:-}" ]; then
				WRONG=true
				ERR_ARG_MSG="${ERR_COLOR} missing parameter for option $1"
				break
			fi
			if ! [[ "$2" =~ ^[0-9]+$ ]] || [ "$2" -lt 1024 ] || [ "$2" -gt 65535 ]; then
				WRONG=true
				ERR_ARG_MSG="${ERR_COLOR} port must be an integer in range 1024..65535."
				break
			fi
			if ! port_available "$ADDRESS" "$2"; then
				WRONG=true
				ERR_ARG_MSG="${ERR_COLOR} specified port $2 is currently in use."
				break
			fi
			PORT="$2"
			PORT_SET="\\e[2m(user)\\e[0m"
			shift 2
			;;
		-a|--addr)
			if [ -z "${2:-}" ]; then
				WRONG=true
				ERR_ARG_MSG="${ERR_COLOR} missing parameter for option $1"
				break
			fi
			if [ "$2" = "localhost" ]; then
				ADDRESS="127.0.0.1"
				ADDRESS_SET="\\e[2m(user)\\e[0m"
				shift 2
				continue
			fi
			if ! python3 - "$2" <<'PY' >/dev/null 2>&1
import ipaddress,sys
ipaddress.IPv4Address(sys.argv[1])
PY
			then
				WRONG=true
				ERR_ARG_MSG="${ERR_COLOR} $2 is not a valid IPv4 address."
				break
			fi
			ADDRESS="$2"
			ADDRESS_SET="\\e[2m(user)\\e[0m"
			shift 2
			;;
		-h|--help)
			HELP=true
			shift
			;;
		-v|--version)
			printf '%s v%s\n' "$SCRIPT_NAME" "$SCRIPT_VERSION"
			exit 0
			;;
		-c|--clean)
			rm -f "${BACKUP_DIR}/*"
			echo -e "$DONE_COLOR Old backups removed."
			exit 0
			;;
		*)
			WRONG=true
			ERR_ARG_MSG="${ERR_COLOR} invalid parameter $1.\n${INFO_COLOR} try -h|--help for more information."
			break
			;;
	esac
done

if [ -z "$PORT" ]; then
	PORT="$(find_port)" || { printf '%b\n' "${ERR_COLOR} no available port found"; exit 1; }
fi
if ! [[ "$PORT" =~ ^[0-9]+$ ]] || [ "$PORT" -lt 1024 ] || [ "$PORT" -gt 65535 ]; then
	printf '%b\n' "${ERR_COLOR} invalid port $PORT (must be 1024..65535)"
	exit 1
fi

line(){
	local word="$1" width=45 length=${#1} color
	if $WRONG; then color="$RED"; else color="$BLU"; fi
	printf '%s\n' "$color"
	printf '=%.0s' $(seq 1 $((width - 3)))
	printf '\r\e[%sC %s%s\e[0m \e[1B\n' "$((width/2 - length/2 - 3))" "$GRN" "$word"
}

init_info(){
	if ! $WRONG && ! $HELP && command -v stty >/dev/null 2>&1 && [ -t 0 ]; then stty -echo; fi
	line "HELLO THERE"
	printf '%b\n' "
${YLW}Termux
${GRN}  _____             __ 
 / ____|           / _|
| |     ___  _ __ | |_ 
| |    / _ \| '_ \\|  _|
| |___| (_) | | | | |  
 \\_____\\___/|_| |_|_|  
           ${YLW}GUI ${RED}v${SCRIPT_VERSION}\e[0m

${BLU}Made by ${GRN}${SCRIPT_AUTHOR}${BLU} (c) ${SCRIPT_YEAR}\e[0m"
	if $WRONG; then
		line ERROR
		printf '\n%b\n' "$ERR_ARG_MSG"
		line "TRY TO USE -h --help INSTEAD"
		printf '\n'
		exit 1
	fi
	if $HELP; then
		line DESCRIPTION
		printf '%b\n' "
TermuxConf is a local configuration editor for ~/.termux/termux.properties.
It preserves comments and unrelated settings, creates dated backups, and lets you restore older configurations.
The Extra Keys editor imitates the Termux key panel and supports labels, macros and popup actions."
		line OPTIONS
		printf '%b\n' "
${INFO_COLOR} Usage:${GRN} $(basename "$0") [OPTIONS]\e[0m

${INFO_COLOR} Options:\e[0m
    ${GRN}-p --port <number>\e[0m        Select the local web server port [1024..65535].
    ${GRN}-a --addr <IPv4>\e[0m         Select the bind address (default: 127.0.0.1).
    ${GRN}-h --help\e[0m                Show this help.
    ${GRN}-v --version\e[0m             Show version.

${INFO_COLOR} Start the web interface, edit settings, save, then run termux-reload-settings automatically.\e[0m"
		line LICENSE
		printf '%b\n' "
This project is licensed under the GNU Affero General Public License v3 (AGPLv3).
Redistributed or modified versions must comply with AGPLv3 and provide the corresponding source code."
		line "THANKS FOR USING TERMUXCONF"
		printf '\n'
		exit 0
	fi
	line CONFIG
	printf '%b\n' "
${BLU}>\e[0m Working port: $PORT ${PORT_SET:-\e[2m(random)\e[0m}
${BLU}>\e[0m Server address: \e[1;4;36mhttp://$ADDRESS:$PORT\e[0m ${ADDRESS_SET:-}
"
	if [ "$ADDRESS" != "127.0.0.1" ] && [ "$ADDRESS" != "0.0.0.0" ]; then
		printf '%b\n' "${YLW}[ INFO ]\e[0m: A non-loopback address may expose the configuration editor to other devices on the network."
	fi
	printf '%b\n' "${INFO_COLOR} press CTRL+C to abort or exit.\e[0m"
	for i in {0..2}; do
		j=$((3-i))
		printf '\r\e[K%b server will start in %ss...' "$INFO_COLOR" "$j"
		sleep 1
	done
	printf '\r\e[J%b starting...\n' "$INFO_COLOR"
	line SERVER
	printf '\n'
}

init_info

export SCRIPT_AUTHOR SCRIPT_NAME SCRIPT_VERSION SCRIPT_LICENSE SCRIPT_YEAR
export ADDRESS PORT ROOT="$WORK" CONFIG BACKUP_DIR

[ -n "$LOGO_B64" ] && decode_b64_to_file "$LOGO_B64" "$WORK/icons/logo.png" || true
[ -n "$WEBSITE_B64" ] && decode_b64_to_file "$WEBSITE_B64" "$WORK/icons/site.png" || true
[ -n "$GITHUB_B64" ] && decode_b64_to_file "$GITHUB_B64" "$WORK/icons/gh.png" || true
[ -n "$TOTAL_B64" ] && decode_b64_to_file "$TOTAL_B64" "$WORK/icons/total.png" || true
[ -n "$LOADING_B64" ] && decode_b64_to_file "$LOADING_B64" "$WORK/icons/loading.gif" || true
[ -n "$archive_b64" ] && decode_b64_to_file "$archive_b64" "$WORK/icons/archive.png" || true
[ -n "$image_b64" ] && decode_b64_to_file "$image_b64" "$WORK/icons/image.png" || true
[ -n "$movie_b64" ] && decode_b64_to_file "$movie_b64" "$WORK/icons/movie.png" || true
[ -n "$audio_b64" ] && decode_b64_to_file "$audio_b64" "$WORK/icons/audio.png" || true
[ -n "$text_b64" ] && decode_b64_to_file "$text_b64" "$WORK/icons/text.png" || true
[ -n "$misc_b64" ] && decode_b64_to_file "$misc_b64" "$WORK/icons/misc.png" || true

