cat >"$WORK/app.js" <<'JS'
const ICON_LOGO='/icons/logo.png';
const ICON_LOADING='/icons/loading.gif';
let configData=null;
let changedSettings={};
let extraKeys=[];
let extraKeysDirty=false;
let selectedRow=-1;
let selectedKey=-1;
let activeEditorPopup=false;
const BOOL_KEYS=new Set(['allow-external-apps','disable-terminal-session-change-toast','hide-soft-keyboard-on-startup','extra-keys-text-all-caps','fullscreen','use-fullscreen-workaround','use-black-ui','disable-hardware-keyboard-shortcuts','enforce-char-based-input','ctrl-space-workaround']);
const KEY_SUGGESTIONS=['ESC','TAB','CTRL','ALT','FN','SPACE','HOME','END','PGUP','PGDN','INS','DEL','BKSP','UP','LEFT','RIGHT','DOWN','ENTER','BACKSLASH','QUOTE','APOSTROPHE','F1','F2','F3','F4','F5','F6','F7','F8','F9','F10','F11','F12','KEYBOARD','DRAWER','-','|','/','\\','#','$','(',')','{','}','[',']',':',';','_','=','+'];

async function request(url,opts={},timeout=30000){
	const controller=new AbortController();
	const timer=setTimeout(()=>controller.abort(),timeout);
	try{return await fetch(url,{...opts,signal:controller.signal});}
	finally{clearTimeout(timer);}
}
function showOverlay(message='Working...'){
	const overlay=document.getElementById('overlay');
	document.getElementById('overlayMsg').textContent=message;
	document.getElementById('loadingGif').src=ICON_LOADING;
	overlay.classList.remove('hidden');
}
function hideOverlay(){document.getElementById('overlay').classList.add('hidden');}
function showModal(message,variant='info'){
	const inner=document.getElementById('modalInner');
	inner.classList.remove('error','success','info');
	inner.classList.add(variant);
	document.getElementById('modalContent').textContent=message;
	document.getElementById('modal').classList.remove('hidden');
}
function hideModal(){document.getElementById('modal').classList.add('hidden');}
function status(message,kind=''){
	const el=document.getElementById('statusLine');
	el.textContent=message||'';
	el.classList.remove('error','success');
	if(kind) el.classList.add(kind);
	el.hidden=!message;
}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function make(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function field(labelText,control,key){
	const wrap=make('div','setting');
	const main=make('div','setting-main');
	main.appendChild(make('div','setting-label',labelText));
	wrap.appendChild(main);
	wrap.appendChild(control);
	return wrap;
}
function markSetting(key,wrap,value){
	changedSettings[key]=value;
	wrap.classList.add('changed');
}
function renderSettings(){
	const root=document.getElementById('settings');
	root.innerHTML='';
	const groups=new Map();
	for(const def of configData.definitions){
		if(!groups.has(def.group))groups.set(def.group,[]);
		groups.get(def.group).push(def);
	}
	for(const [groupName,defs] of groups){
		const section=make('div','setting-group');
		section.appendChild(make('h3','',groupName));
		const grid=make('div','setting-grid');
		for(const def of defs){
			const current=configData.settings[def.key]||{};
			let value=current.value!==null&&current.value!==undefined?String(current.value):'__default__';
			if(def.type==='shortcut'){
				const controls=make('div','shortcut-controls');
				const enabled=!!current.enabled;
				const toggle=make('button','bool-toggle '+(enabled?'on':'off'),enabled?'ON':'OFF');
				toggle.type='button';toggle.setAttribute('aria-pressed',String(enabled));
				const input=make('input');input.type='text';input.value=value==='__default__'?'':value;input.placeholder=def.placeholder||'ctrl + key';input.disabled=!enabled;input.autocomplete='off';
				controls.appendChild(toggle);controls.appendChild(input);
				const wrapped=field(def.label,controls,def.key);
				const update=()=>markSetting(def.key,{enabled:toggle.getAttribute('aria-pressed')==='true',value:input.value===' '?'SPACE':input.value},wrapped);
				toggle.onclick=()=>{const next=toggle.getAttribute('aria-pressed')!=='true';toggle.setAttribute('aria-pressed',String(next));toggle.textContent=next?'ON':'OFF';toggle.classList.toggle('on',next);toggle.classList.toggle('off',!next);input.disabled=!next;update();};
				input.oninput=()=>{if(input.value===' '){input.value='SPACE';}update();};
				grid.appendChild(wrapped);continue;
			}
			if(BOOL_KEYS.has(def.key)){
				const isOn=String(value==='__default__'?def.default:value)==='true';
				const button=make('button','bool-toggle '+(isOn?'on':'off'),isOn?'ON':'OFF');
				button.type='button';button.setAttribute('aria-pressed',String(isOn));
				const wrapped=field(def.label,button,def.key);
				button.onclick=()=>{const next=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(next));button.textContent=next?'ON':'OFF';button.classList.toggle('on',next);button.classList.toggle('off',!next);markSetting(def.key,wrapped,next?'true':'false');};
				grid.appendChild(wrapped);continue;
			}
			let control;
			if(def.type==='select'){
				control=make('select');
				for(const opt of def.options){const option=make('option','',opt.label);option.value=opt.value;control.appendChild(option);}
				if(value!=='__default__'&&!def.options.some(o=>o.value===value)){const option=make('option','',`Current: ${value}`);option.value=value;control.appendChild(option);}
				control.value=value;
			}else{
				control=make('input');control.type=def.type==='number'?'number':'text';
				if(def.type==='number'){if(def.min!==undefined)control.min=String(def.min);if(def.max!==undefined)control.max=String(def.max);control.step='1';}
				control.value=value==='__default__'?'':value;control.placeholder=def.placeholder||(value==='__default__'?'System default':'');
			}
			const wrapped=field(def.label,control,def.key);
			if(def.type==='select')control.onchange=()=>markSetting(def.key,wrapped,control.value);
			else control.onchange=()=>markSetting(def.key,wrapped,control.value===''?'__default__':control.value);
			grid.appendChild(wrapped);
		}
		section.appendChild(grid);root.appendChild(section);
	}
}
function keyLabel(item){
	if(item.display)return String(item.display);
	const value=String(item.value||'');
	if(value.toUpperCase()==='DRAWER')return '☰';
	if(value.toUpperCase()==='KEYBOARD')return '⌨';
	if(item.kind==='key'&&value===' ')return 'SPACE';
	return value;
}
function normalizeKey(item){
	if(!item||typeof item!=='object')return {kind:'key',value:String(item??''),display:'',popup:null};
	let value=String(item.value??'');let kind=item.kind==='macro'?'macro':'key';if(value===' '){value='SPACE';kind='key';}
	let popup=item.popup?{kind:item.popup.kind==='macro'?'macro':'key',value:String(item.popup.value??''),display:String(item.popup.display??'')}:null;
	if(popup&&popup.value===' '){popup.value='SPACE';popup.kind='key';}
	return {kind,value,display:String(item.display??''),popup};
}
function renderKeyboard(){
	const root=document.getElementById('keyboardGrid');root.innerHTML='';
	if(!extraKeys.length){root.appendChild(make('div','editor-empty','No rows configured. Add a row to begin.'));return;}
	extraKeys.forEach((row,ri)=>{
		const rowEl=make('div','key-row');rowEl.style.gridTemplateColumns=`repeat(${Math.max(1,row.length)},minmax(0,1fr))`;
		row.forEach((raw,ki)=>{
			const item=normalizeKey(raw);
			const visual=keyLabel(item)||'∅';
			const special=!item.display&&['DRAWER','KEYBOARD'].includes(String(item.value).toUpperCase());
			const button=make('button','extra-key'+(ri===selectedRow&&ki===selectedKey?' selected':'')+(special?' special-key':''));button.type='button';
			const label=make('span','key-label',visual);button.appendChild(label);
			if(item.popup)button.appendChild(make('span','popup-mark','↟'));
			button.title=`Row ${ri+1}, key ${ki+1}${item.popup?' — popup configured':''}`;
			button.onclick=()=>selectKey(ri,ki);
			rowEl.appendChild(button);
		});
		root.appendChild(rowEl);
	});
	document.getElementById('removeRowBtn').disabled=selectedRow<0||extraKeys.length<2;
	document.getElementById('removeKeyBtn').disabled=selectedRow<0||selectedKey<0||!extraKeys[selectedRow]||extraKeys[selectedRow].length<2;
}
function selectKey(row,key){selectedRow=row;selectedKey=key;renderKeyboard();renderKeyEditor();}
function selectedItem(){if(selectedRow<0||selectedKey<0||!extraKeys[selectedRow]||!extraKeys[selectedRow][selectedKey])return null;return normalizeKey(extraKeys[selectedRow][selectedKey]);}
function markKeys(){extraKeysDirty=true;renderKeyboard();}
function renderKeyEditor(){
	const root=document.getElementById('keyEditor');root.innerHTML='';
	const item=selectedItem();
	if(!item){root.appendChild(make('div','editor-empty','Select a key in the panel above to edit it.'));return;}
	const title=make('div','editor-title',`Editing row ${selectedRow+1}, key ${selectedKey+1}`);root.appendChild(title);
	const grid=make('div','editor-grid');
	const kind=make('select');[['key','Single key / action'],['macro','Macro / key sequence']].forEach(([v,l])=>{const o=make('option','',l);o.value=v;kind.appendChild(o)});kind.value=item.kind;
	const value=make('input');value.type='text';value.value=item.value===' '?'SPACE':item.value;value.setAttribute('list','key-suggestions');value.placeholder=item.kind==='macro'?'Example: CTRL c':'Example: ESC';
	const datalist=make('datalist');datalist.id='key-suggestions';KEY_SUGGESTIONS.forEach(k=>{const o=make('option');o.value=k;datalist.appendChild(o)});
	const display=make('input');display.type='text';display.value=item.display;display.placeholder='Button label (optional)';
	grid.appendChild(editorField('Main action type',kind));grid.appendChild(editorField(item.kind==='macro'?'Macro sequence':'Key / action',value));grid.appendChild(editorField('Button label (display)',display));
	root.appendChild(grid);root.appendChild(datalist);
	const popupToggle=make('input');popupToggle.type='checkbox';popupToggle.checked=!!item.popup;
	const check=make('label','check-row');check.appendChild(popupToggle);check.appendChild(document.createTextNode('Enable popup action (swipe up in Termux)'));root.appendChild(check);
	const popupArea=make('div','popup-box');popupArea.style.display=item.popup?'block':'none';root.appendChild(popupArea);
	function updateMain(){
		const target=normalizeKey(extraKeys[selectedRow][selectedKey]);
		const hadPopup=!!target.popup;
		target.kind=kind.value;if(value.value===' '){value.value='SPACE';if(kind.value==='macro'){kind.value='key';target.kind='key';}}target.value=value.value;target.display=display.value;
		if(popupToggle.checked&&!target.popup)target.popup={kind:'key',value:'',display:''};
		if(!popupToggle.checked)target.popup=null;
		extraKeys[selectedRow][selectedKey]=target;popupArea.style.display=popupToggle.checked?'block':'none';extraKeysDirty=true;renderKeyboard();
		if(popupToggle.checked&&!hadPopup)renderPopupFields(popupArea,target);
	}
	kind.onchange=()=>{if(kind.value==='macro'&&!value.value)value.value='CTRL c';updateMain();};
	value.oninput=updateMain;display.oninput=updateMain;
	popupToggle.onchange=()=>{updateMain();};
	if(item.popup)renderPopupFields(popupArea,item);
}
function editorField(labelText,control){const wrap=make('div','editor-field');wrap.appendChild(make('label','',labelText));wrap.appendChild(control);return wrap;}
function renderPopupFields(area,item){
	area.innerHTML='';
	const title=make('div','popup-title','Popup action');area.appendChild(title);
	const popup=item.popup||{kind:'key',value:'',display:''};
	const grid=make('div','editor-grid');
	const kind=make('select');[['key','Single key / action'],['macro','Macro / key sequence']].forEach(([v,l])=>{const o=make('option','',l);o.value=v;kind.appendChild(o)});kind.value=popup.kind;
	const value=make('input');value.type='text';value.value=popup.value===' '?'SPACE':popup.value;value.setAttribute('list','key-suggestions');value.placeholder=popup.kind==='macro'?'Example: CTRL c':'Example: |';
	const display=make('input');display.type='text';display.value=popup.display;display.placeholder='Popup label (optional)';
	grid.appendChild(editorField('Popup action type',kind));grid.appendChild(editorField(popup.kind==='macro'?'Popup macro':'Popup key / action',value));grid.appendChild(editorField('Popup label (display)',display));area.appendChild(grid);
	function update(){
		const target=normalizeKey(extraKeys[selectedRow][selectedKey]);
		if(value.value===' '){value.value='SPACE';if(kind.value==='macro')kind.value='key';}target.popup={kind:kind.value,value:value.value,display:display.value};
		extraKeys[selectedRow][selectedKey]=target;extraKeysDirty=true;renderKeyboard();
	}
	kind.onchange=()=>{if(kind.value==='macro'&&!value.value)value.value='CTRL c';update();};value.oninput=update;display.oninput=update;
}
function renderBackups(backups){
	const select=document.getElementById('backupSelect');select.innerHTML='';
	if(!backups.length){const o=make('option','','No backups found');o.value='';select.appendChild(o);select.disabled=true;document.getElementById('restoreBtn').disabled=true;document.getElementById('backupInfo').textContent='No snapshots have been created yet.';return;}
	select.disabled=false;
	for(const item of backups){const o=make('option','',item.date);o.value=item.name;select.appendChild(o);}
	if(backups.length>1&&/^(session|manual|before-restore)(-|$)/.test(backups[0].reason))select.selectedIndex=1;
	document.getElementById('restoreBtn').disabled=false;
	document.getElementById('backupInfo').textContent=`${backups.length} dated backup(s). The newest copy is shown first.`;
}
async function loadConfig(){
	showOverlay('Reading Termux settings...');
	try{
		const response=await request('/api/config');
		const data=await response.json();
		if(!response.ok||!data.ok)throw new Error(data.error||'Unable to read config');
		configData=data;changedSettings={};extraKeys=(data.extra_keys||[]).map(row=>row.map(normalizeKey));extraKeysDirty=false;selectedRow=extraKeys.length?0:-1;selectedKey=extraKeys[0]&&extraKeys[0].length?0:-1;
		renderSettings();renderKeyboard();renderKeyEditor();renderBackups(data.backups||[]);
		status('');
		if(data.extra_keys_error)status(`Extra Keys could not be parsed: ${data.extra_keys_error}. Keyboard editing is disabled to protect the existing layout.`,'error');
		document.getElementById('addKeyBtn').disabled=!data.extra_keys_editable;
		document.getElementById('addRowBtn').disabled=!data.extra_keys_editable;
		document.getElementById('removeRowBtn').disabled=!data.extra_keys_editable||extraKeys.length<2;
		document.getElementById('removeKeyBtn').disabled=!data.extra_keys_editable;
	}catch(e){status(`Error: ${e.message}`,'error');showModal(e.message,'error');}
	finally{hideOverlay();}
}
async function refreshAll(){if((Object.keys(changedSettings).length||extraKeysDirty)&&!confirm('Discard unsaved changes and reload the configuration?'))return;loadConfig();}
async function saveChanges(){
	if(!Object.keys(changedSettings).length&&!extraKeysDirty){showModal('No changes to save.','info');return;}
	const payload={settings:changedSettings};
	if(extraKeysDirty){
		if(!configData.extra_keys_editable){showModal('The current Extra Keys configuration could not be parsed safely. Keyboard saving is disabled.','error');return;}
		payload.extra_keys=extraKeys;
	}
	showOverlay('Saving configuration...');
	try{
		const response=await request('/api/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)},60000);
		const result=await response.json();
		if(!response.ok||!result.ok)throw new Error(result.error||'Save failed');
		changedSettings={};extraKeysDirty=false;
		await loadConfig();
		const message=result.reload_ok?'Configuration saved. Backup created and termux-reload-settings executed.':'Configuration saved and backed up, but termux-reload-settings could not be executed. Reload settings manually in Termux.';
		status(message,result.reload_ok?'success':'');showModal(message,result.reload_ok?'success':'info');
	}catch(e){status(`Save failed: ${e.message}`,'error');showModal(e.message,'error');}
	finally{hideOverlay();}
}
async function createBackup(){
	showOverlay('Creating backup...');
	try{
		const response=await request('/api/backup',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});
		const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Backup failed');
		await loadConfig();status(result.message,'success');showModal(result.message,'success');
	}catch(e){showModal(e.message,'error');}
	finally{hideOverlay();}
}
async function restoreBackup(){
	const name=document.getElementById('backupSelect').value;
	if(!name)return;
	const selected=document.getElementById('backupSelect').selectedOptions[0]?.textContent||name;
	if(!confirm(`Restore this configuration?\n\n${selected}\n\nThe current file will be backed up first.`))return;
	showOverlay('Restoring configuration...');
	try{
		const response=await request('/api/restore',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name})},60000);
		const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Restore failed');
		await loadConfig();
		const message=result.reload_ok?'Previous configuration restored. The current configuration was backed up first.':'Configuration restored, but automatic reload failed. Run termux-reload-settings manually.';
		status(message,result.reload_ok?'success':'');showModal(message,result.reload_ok?'success':'info');
	}catch(e){showModal(e.message,'error');}
	finally{hideOverlay();}
}
function addKey(){
	if(!configData.extra_keys_editable)return;
	if(!extraKeys.length)extraKeys.push([]);
	const row=extraKeys[selectedRow>=0?selectedRow:extraKeys.length-1];
	row.push({kind:'key',value:'ESC',display:'',popup:null});selectedRow=extraKeys.indexOf(row);selectedKey=row.length-1;extraKeysDirty=true;renderKeyboard();renderKeyEditor();
}
function addRow(){
	if(!configData.extra_keys_editable)return;
	const count=extraKeys.length?(extraKeys[0].length||7):7;
	const starter=['ESC','TAB','CTRL','ALT','LEFT','DOWN','RIGHT'];extraKeys.push(Array.from({length:count},(_,i)=>({kind:'key',value:starter[i%starter.length],display:'',popup:null}))); 
	selectedRow=extraKeys.length-1;selectedKey=0;extraKeysDirty=true;renderKeyboard();renderKeyEditor();
}
function removeRow(){
	if(selectedRow<0||extraKeys.length<2)return;
	extraKeys.splice(selectedRow,1);selectedRow=Math.min(selectedRow,extraKeys.length-1);selectedKey=0;extraKeysDirty=true;renderKeyboard();renderKeyEditor();
}
function removeKey(){
	if(selectedRow<0||selectedKey<0||extraKeys[selectedRow].length<2)return;
	extraKeys[selectedRow].splice(selectedKey,1);selectedKey=Math.min(selectedKey,extraKeys[selectedRow].length-1);extraKeysDirty=true;renderKeyboard();renderKeyEditor();
}
document.addEventListener('DOMContentLoaded',()=>{
	document.getElementById('reloadPage').onclick=()=>window.location.reload();
	document.getElementById('refreshBtn').onclick=refreshAll;
	document.getElementById('saveBtn').onclick=saveChanges;
	document.getElementById('backupNow').onclick=createBackup;
	document.getElementById('restoreBtn').onclick=restoreBackup;
	document.getElementById('addRowBtn').onclick=addRow;
	document.getElementById('removeRowBtn').onclick=removeRow;
	document.getElementById('addKeyBtn').onclick=addKey;
	document.getElementById('removeKeyBtn').onclick=removeKey;
	document.getElementById('modalClose').onclick=hideModal;
	document.getElementById('siteicon').src='/icons/site.png';document.getElementById('ghicon').src='/icons/gh.png';
	document.getElementById('logo').src=ICON_LOGO;document.getElementById('loadingGif').src=ICON_LOADING;
	document.getElementById('meta_name').textContent='__SCRIPT_NAME__';
	document.getElementById('meta_author').textContent='__SCRIPT_AUTHOR__';
	document.getElementById('meta_version').textContent='v__SCRIPT_VERSION__';
	document.getElementById('meta_license').textContent='__SCRIPT_LICENSE__';
	window.addEventListener('beforeunload',e=>{if(Object.keys(changedSettings).length||extraKeysDirty){e.preventDefault();e.returnValue='';}});
	loadConfig();
});
