def physical_lines(text):
	return text.splitlines(keepends=True)

def has_continuation(line):
	s=line.rstrip('\r\n')
	count=0
	for ch in reversed(s):
		if ch=='\\': count+=1
		else: break
	return count%2==1

def property_blocks(lines):
	blocks=[]
	i=0
	pattern=re.compile(r'^\s*([^#!\s][^=:]*?)\s*[:=]\s*(.*)$')
	while i<len(lines):
		line=lines[i].rstrip('\r\n')
		m=pattern.match(line)
		if not m:
			i+=1;continue
		key=m.group(1).strip()
		value=m.group(2)
		start=i
		while has_continuation(lines[i]) and i+1<len(lines):
			value=value[:-1]
			i+=1
			value+=lines[i].lstrip(' \t\f').rstrip('\r\n')
		blocks.append({'key':key,'start':start,'end':i+1,'value':value,'active':not lines[start].lstrip().startswith('#')})
		i+=1
	return blocks

def read_config_text():
	try:
		with open(CONFIG,'r',encoding='utf-8',errors='replace',newline='') as f: return f.read()
	except FileNotFoundError: return ''

def active_properties(text):
	lines=physical_lines(text)
	out={}
	for block in property_blocks(lines):
		if block['active']: out[block['key']]=block['value'].strip()
	return out

def decode_quoted(raw):
	out=[];i=0
	while i<len(raw):
		if raw[i]=='\\' and i+1<len(raw):
			i+=1;c=raw[i]
			out.append({'n':'\n','r':'\r','t':'\t','b':'\b','f':'\f'}.get(c,c))
		else: out.append(raw[i])
		i+=1
	return ''.join(out)

class ExtraKeysParser:
	def __init__(self,text): self.text=text;self.i=0;self.tokens=self.tokenize(text);self.pos=0
	def tokenize(self,text):
		tokens=[];i=0
		while i<len(text):
			c=text[i]
			if c.isspace():i+=1;continue
			if c in '[]{}:,':tokens.append(c);i+=1;continue
			if c in '\"\'':
				quote=c;i+=1;raw=[]
				while i<len(text):
					if text[i]=='\\' and i+1<len(text):raw.extend([text[i],text[i+1]]);i+=2;continue
					if text[i]==quote:i+=1;break
					raw.append(text[i]);i+=1
				tokens.append(('str',decode_quoted(''.join(raw))));continue
			start=i
			while i<len(text) and not text[i].isspace() and text[i] not in '[]{}:,':i+=1
			if start==i:raise ValueError('unexpected token')
			tokens.append(('bare',text[start:i]))
		return tokens
	def peek(self):return self.tokens[self.pos] if self.pos<len(self.tokens) else None
	def pop(self):
		t=self.peek()
		if t is None:raise ValueError('unexpected end of Extra Keys value')
		self.pos+=1;return t
	def parse_value(self):
		t=self.pop()
		if t=='[':
			out=[]
			if self.peek()==']':self.pop();return out
			while True:
				out.append(self.parse_value())
				n=self.pop()
				if n==']':break
				if n!=',':raise ValueError('expected comma in array')
			return out
		if t=='{':
			out={}
			if self.peek()=='}':self.pop();return out
			while True:
				k=self.pop()
				if isinstance(k,tuple):key=k[1]
				elif isinstance(k,str):key=k
				else:raise ValueError('invalid object key')
				if self.pop()!=':':raise ValueError('expected colon in object')
				out[key]=self.parse_value()
				n=self.pop()
				if n=='}':break
				if n!=',':raise ValueError('expected comma in object')
			return out
		if isinstance(t,tuple):return t[1]
		if isinstance(t,str):return t
		raise ValueError('invalid value')
	def parse(self):
		result=self.parse_value()
		if self.peek() is not None:raise ValueError('unexpected trailing content')
		return result

def normalize_action(value):
	if isinstance(value,str):return {'kind':'key','value':'SPACE' if value==' ' else value,'display':''}
	if isinstance(value,dict):
		kind='macro' if 'macro' in value else 'key'
		val=value.get('macro') if kind=='macro' else value.get('key','')
		val=str(val if val is not None else '')
		if val==' ':kind='key';val='SPACE'
		return {'kind':kind,'value':val,'display':str(value.get('display','') or '')}
	raise ValueError('key action is not a string or object')

def normalize_extra_keys(value):
	if not isinstance(value,list) or not value:raise ValueError('Extra Keys must be a non-empty array of rows')
	rows=[]
	for row in value:
		if not isinstance(row,list) or not row:raise ValueError('each Extra Keys row must contain at least one key')
		out=[]
		for raw in row:
			main=normalize_action(raw)
			popup_raw=raw.get('popup') if isinstance(raw,dict) else None
			popup=normalize_action(popup_raw) if popup_raw is not None else None
			main['popup']=popup
			out.append(main)
		rows.append(out)
	return rows

def get_extra_keys(text):
	lines=physical_lines(text)
	blocks=[b for b in property_blocks(lines) if b['key']=='extra-keys' and b['active']]
	if not blocks:return DEFAULT_EXTRA_KEYS,None
	try:
		parsed=ExtraKeysParser(blocks[-1]['value'].strip()).parse()
		return normalize_extra_keys(parsed),None
	except Exception as e:
		return [],str(e)

def quote_termux(value):
	return json.dumps(str(value),ensure_ascii=False,separators=(',',':'))

def serialize_action(item,is_popup=False):
	kind=item.get('kind','key')
	value=str(item.get('value',''))
	display=str(item.get('display','') or '')
	popup=item.get('popup') if not is_popup else None
	if kind=='key' and not display and not popup:return quote_termux(value)
	parts=[]
	if kind=='macro':parts.append('macro: '+quote_termux(value))
	else:parts.append('key: '+quote_termux(value))
	if display:parts.append('display: '+quote_termux(display))
	if popup:parts.append('popup: '+serialize_action(popup,True))
	return '{'+', '.join(parts)+'}'

def serialize_extra_keys(rows):
	if not isinstance(rows,list) or not rows or len(rows)>8:raise ValueError('Extra Keys must have 1..8 rows')
	out=['extra-keys = [ \\\n']
	for ri,row in enumerate(rows):
		if not isinstance(row,list) or not row or len(row)>14:raise ValueError('each row must have 1..14 keys')
		out.append('\t[ \\\n')
		for ki,item in enumerate(row):
			if not isinstance(item,dict):raise ValueError('invalid key entry')
			kind=item.get('kind','key')
			val=str(item.get('value',''))
			if kind not in ('key','macro') or not val or len(val)>200 or '\n' in val or '\r' in val:raise ValueError('each key or macro must have a valid value (1..200 characters)')
			display=str(item.get('display','') or '')
			if len(display)>40 or '\n' in display or '\r' in display:raise ValueError('display labels must be 40 characters or shorter')
			popup=item.get('popup')
			if popup is not None:
				if not isinstance(popup,dict) or popup.get('kind','key') not in ('key','macro'):raise ValueError('invalid popup action')
				if not str(popup.get('value','')) or len(str(popup.get('value','')))>200 or '\n' in str(popup.get('value','')) or '\r' in str(popup.get('value','')):raise ValueError('popup key or macro is required and must be one line')
				if len(str(popup.get('display','') or ''))>40 or '\n' in str(popup.get('display','') or '') or '\r' in str(popup.get('display','') or ''):raise ValueError('popup label must be a single line of 40 characters or shorter')
			out.append('\t\t'+serialize_action(item)+(',' if ki<len(row)-1 else '')+' \\\n')
		out.append('\t]'+(',' if ri<len(rows)-1 else '')+(' \\\n' if ri<len(rows)-1 or ri==len(rows)-1 else '\n'))
	out.append(']\n')
	return ''.join(out)

def commented_property_value(text,key):
	pattern=re.compile(r'^\s*#\s*'+re.escape(key)+r'\s*[:=]\s*(.*?)\s*$')
	found=[]
	for line in physical_lines(text):
		match=pattern.match(line.rstrip('\r\n'))
		if match:found.append(match.group(1).strip())
	return found[-1] if found else None

def set_shortcut_text(text,key,enabled,value):
	lines=physical_lines(text)
	pattern=re.compile(r'^(\s*)(#\s*)?'+re.escape(key)+r'\s*[:=]\s*(.*?)(\r?\n)?$')
	matches=[]
	for i,line in enumerate(lines):
		match=pattern.match(line.rstrip('\r\n'))
		if match:
			matches.append((i,match.group(1),bool(match.group(2)),match.group(3),line.endswith('\n')))
	if not matches:
		if not value and not enabled:return text
		if text and not text.endswith('\n'):lines.append('\n')
		if lines and lines[-1].strip():lines.append('\n')
		lines.append(('# ' if not enabled else '')+f'{key} = {value}\n')
		return ''.join(lines)
	last_i=matches[-1][0]
	for i,indent,was_commented,old_value,has_nl in matches:
		ending='\n' if has_nl else ''
		if i!=last_i:
			if not was_commented:lines[i]=f'{indent}# {key} = {old_value}{ending}'
			continue
		lines[i]=f'{indent}'+('' if enabled else '# ')+f'{key} = {value}{ending}'
	return ''.join(lines)

def ensure_generated_header(text):
	header='# Generated by TermuxConf v1.0.0 (author: Kamil BuriXon Burek)\n'
	lines=[line for line in physical_lines(text) if not line.lstrip().startswith('# Generated by TermuxConf ')]
	return header+''.join(lines)

def format_value(text,key):
	for b in property_blocks(physical_lines(text)):
		if b['key']==key and b['active']:
			return b['value'].strip()
	return None

def set_property_text(text,key,value):
	lines=physical_lines(text)
	blocks=[b for b in property_blocks(lines) if b['key']==key and b['active']]
	if value=='__default__':
		for b in reversed(blocks):
			for i in range(b['start'],b['end']):
				line=lines[i]
				if line.strip() and not line.lstrip().startswith('#'):lines[i]='# '+line
		return ''.join(lines)
	if key=='extra-keys':new_lines=value.splitlines(keepends=True)
	else:new_lines=[f'{key} = {value}\n']
	if not new_lines or not new_lines[-1].endswith('\n'):new_lines=[x if x.endswith('\n') else x+'\n' for x in new_lines]
	if blocks:
		b=blocks[-1]
		lines[b['start']:b['end']]=new_lines
		return ''.join(lines)
	if text and not text.endswith('\n'):lines.append('\n')
	if lines and lines[-1].strip():lines.append('\n')
	lines.extend(new_lines)
	return ''.join(lines)

def atomic_write(text):
	os.makedirs(os.path.dirname(CONFIG),exist_ok=True)
	old_mode=0o600
	try:old_mode=stat.S_IMODE(os.stat(CONFIG).st_mode)
	except OSError:pass
	fd,tmp=tempfile.mkstemp(prefix='.termuxconf-',dir=os.path.dirname(CONFIG))
	try:
		with os.fdopen(fd,'w',encoding='utf-8',newline='') as f:
			f.write(text);f.flush();os.fsync(f.fileno())
		os.chmod(tmp,old_mode)
		os.replace(tmp,CONFIG)
	except Exception:
		try:os.unlink(tmp)
		except OSError:pass
		raise

def backup_config(reason='manual'):
	os.makedirs(BACKUP_DIR,exist_ok=True)
	if not os.path.isfile(CONFIG):return None
	stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
	base=f'termux.properties.{stamp}-{re.sub("[^a-z0-9-]", "", reason.lower())}.bak'
	name=base;n=1
	while os.path.exists(os.path.join(BACKUP_DIR,name)):
		name=f'termux.properties.{stamp}-{re.sub("[^a-z0-9-]", "", reason.lower())}-{n}.bak';n+=1
	dst=os.path.join(BACKUP_DIR,name)
	shutil.copy2(CONFIG,dst)
	return name

def list_backups():
	items=[]
	try:names=os.listdir(BACKUP_DIR)
	except OSError:return items
	for name in names:
		if not re.fullmatch(r'termux\.properties\.\d{8}-\d{6}(?:-[a-z0-9-]+)?\.bak',name):continue
		path=os.path.join(BACKUP_DIR,name)
		if not os.path.isfile(path):continue
		m=re.match(r'termux\.properties\.(\d{8}-\d{6})-?([a-z0-9-]*)\.bak',name)
		stamp=m.group(1) if m else ''
		reason=(m.group(2) or 'backup') if m else 'backup'
		try:dt=datetime.datetime.strptime(stamp,'%Y%m%d-%H%M%S').strftime('%Y-%m-%d %H:%M:%S')
		except ValueError:dt=stamp
		items.append({'name':name,'date':dt,'reason':reason,'mtime':os.path.getmtime(path)})
	items.sort(key=lambda x:x['mtime'],reverse=True)
	return items

def reload_settings():
	cmd=shutil.which('termux-reload-settings')
	if not cmd:return False,'termux-reload-settings was not found'
	try:
		p=subprocess.run([cmd],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=15)
		return p.returncode==0,(p.stderr.strip() or p.stdout.strip() or '')
	except Exception as e:return False,str(e)

def validate_settings(changes):
	if not isinstance(changes,dict):raise ValueError('settings must be an object')
	clean={}
	for key,value in changes.items():
		if key not in DEF_BY_KEY:raise ValueError(f'unsupported setting: {key}')
		defn=DEF_BY_KEY[key]
		if defn['type']=='shortcut':
			if not isinstance(value,dict):raise ValueError(f'{key} must contain enabled and value fields')
			enabled=value.get('enabled') is True
			shortcut=str(value.get('value','')).strip()
			if enabled and not shortcut:raise ValueError(f'{key}: enter a shortcut or switch it OFF')
			if len(shortcut)>80 or (shortcut and not re.fullmatch(r'[A-Za-z0-9_ +.-]{1,80}',shortcut)):raise ValueError(f'invalid shortcut syntax for {key}')
			clean[key]={'enabled':enabled,'value':shortcut}
			continue
		if value=='__default__':clean[key]='__default__';continue
		if defn['type']=='bool':
			if str(value).lower() not in ('true','false'):raise ValueError(f'{key} must be true or false')
			clean[key]=str(value).lower()
		elif defn['type']=='select':
			allowed=[o['value'] for o in defn.get('options',[])]
			if str(value) not in allowed:raise ValueError(f'invalid value for {key}')
			clean[key]=str(value)
		elif defn['type']=='number':
			try:n=int(str(value))
			except ValueError:raise ValueError(f'{key} must be an integer')
			if n<defn.get('min',-999999) or n>defn.get('max',999999):raise ValueError(f'{key} is outside the allowed range')
			if key=='terminal-cursor-blink-rate' and n!=0 and n<100:raise ValueError('terminal-cursor-blink-rate must be 0 or between 100 and 2000')
			clean[key]=str(n)
		else:
			v=str(value)
			if len(v)>1024 or '\n' in v or '\r' in v:raise ValueError(f'invalid value for {key}')
			if key.startswith('shortcut.') and v and not re.fullmatch(r'[A-Za-z0-9_ +.-]{1,80}',v):raise ValueError(f'invalid shortcut syntax for {key}')
			clean[key]='__default__' if v=='' else v
	return clean

def config_response():
	text=read_config_text();props=active_properties(text)
	settings={}
	for d in SETTING_DEFS:
		key=d['key'];value=props.get(key)
		if d['type']=='shortcut':
			commented=commented_property_value(text,key)
			settings[key]={'value':value if value is not None else (commented or ''),'enabled':value is not None,'configured':value is not None,'effective':value if value is not None else (commented or '')}
			continue
		settings[key]={'value':value,'configured':value is not None,'effective':value if value is not None else d.get('default','__default__')}
		if d['type']=='bool' and value is None:settings[key]['value']=d.get('default','false')
	rows,err=get_extra_keys(text)
	return {'ok':True,'exists':os.path.isfile(CONFIG),'definitions':SETTING_DEFS,'settings':settings,'extra_keys':rows,'extra_keys_editable':err is None,'extra_keys_error':err,'backups':list_backups()}

class Handler(http.server.SimpleHTTPRequestHandler):
	def __init__(self,*args,**kwargs):super().__init__(*args,directory=ROOT,**kwargs)
	def log_message(self,fmt,*args):pass
	def send_json(self,obj,status=200):
		body=json.dumps(obj,ensure_ascii=False).encode('utf-8')
		self.send_response(status);self.send_header('Content-Type','application/json; charset=utf-8');self.send_header('Content-Length',str(len(body)));self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(body)
	def do_GET(self):
		path=urlparse(self.path).path
		if path=='/api/config':
			try:self.send_json(config_response())
			except Exception as e:self.send_json({'ok':False,'error':str(e)},500)
			return
		super().do_GET()
	def do_POST(self):
		path=urlparse(self.path).path
		try:
			length=int(self.headers.get('Content-Length','0'))
			if length>2_000_000:raise ValueError('request is too large')
			payload=json.loads(self.rfile.read(length).decode('utf-8') if length else '{}')
			if path=='/api/save':
				clean=validate_settings(payload.get('settings',{}))
				rows=None
				if 'extra_keys' in payload:
					rows=payload['extra_keys']
					if not isinstance(rows,list) or not rows or len(rows)>8:raise ValueError('Extra Keys must have 1..8 rows')
					for row in rows:
						if not isinstance(row,list) or not row or len(row)>14:raise ValueError('each Extra Keys row must have 1..14 keys')
					extra_text=serialize_extra_keys(rows)
				if not clean and rows is None:self.send_json({'ok':True,'message':'Nothing to save'});return
				backup_config('before-save')
				text=read_config_text()
				for key,value in clean.items():
					if key.startswith('shortcut.'):
						text=set_shortcut_text(text,key,value['enabled'],value['value'])
					else:text=set_property_text(text,key,value)
				if rows is not None:text=set_property_text(text,'extra-keys',extra_text)
				text=ensure_generated_header(text)
				atomic_write(text)
				reload_ok,reload_msg=reload_settings()
				self.send_json({'ok':True,'reload_ok':reload_ok,'reload_message':reload_msg,'backups':list_backups()});return
			if path=='/api/backup':
				name=backup_config('manual')
				if name is None:self.send_json({'ok':False,'error':'The configuration file does not exist yet. Save settings first.'},400);return
				entry=next((item for item in list_backups() if item['name']==name),None)
				label=entry['date'] if entry else name
				self.send_json({'ok':True,'message':f'Backup created: {label}','name':name,'backups':list_backups()});return
			if path=='/api/restore':
				name=payload.get('name','')
				if not isinstance(name,str) or not re.fullmatch(r'termux\.properties\.\d{8}-\d{6}(?:-[a-z0-9-]+)?\.bak',name):raise ValueError('invalid backup name')
				source=os.path.realpath(os.path.join(BACKUP_DIR,name))
				if os.path.dirname(source)!=os.path.realpath(BACKUP_DIR) or not os.path.isfile(source):raise ValueError('backup not found')
				backup_config('before-restore')
				with open(source,'r',encoding='utf-8',errors='replace') as f:restored=f.read()
				atomic_write(restored)
				reload_ok,reload_msg=reload_settings()
				self.send_json({'ok':True,'reload_ok':reload_ok,'reload_message':reload_msg,'backups':list_backups()});return
			self.send_json({'ok':False,'error':'unknown endpoint'},404)
		except Exception as e:
			self.send_json({'ok':False,'error':str(e)},400)

if __name__=='__main__':
	os.makedirs(os.path.dirname(CONFIG),exist_ok=True)
	os.makedirs(BACKUP_DIR,exist_ok=True)
	backup_config('session')
	server=http.server.ThreadingHTTPServer((ADDRESS,PORT),Handler)
	server.serve_forever()
PY

python3 - "$WORK/app.js" <<'PY'
