p=sys.argv[1]
s=open(p,'r',encoding='utf-8').read()
s=s.replace('__SCRIPT_NAME__',os.environ.get('SCRIPT_NAME','TermuxConf'))
s=s.replace('__SCRIPT_AUTHOR__',os.environ.get('SCRIPT_AUTHOR','Kamil BuriXon Burek'))
s=s.replace('__SCRIPT_VERSION__',os.environ.get('SCRIPT_VERSION','1.0.0'))
s=s.replace('__SCRIPT_LICENSE__',os.environ.get('SCRIPT_LICENSE','AGPLv3'))
