setsid python3 "$WORK/server.py" >"$LOG" 2>&1 &
SERVER_PID=$!

tail -n0 -F "$LOG" 2>/dev/null | while IFS= read -r log_line; do
	if printf '%s\n' "$log_line" | grep -q 'Traceback\|Error\|Exception'; then
		printf '%b\n' "${ERR_COLOR} $log_line"
	fi
done &
TAIL_PID=$!

cleanup(){
	printf '\r\e[K%b stopping TermuxConf...\e[J\n' "$INFO_COLOR"
	if [ -n "${SERVER_PID:-}" ] && ps -p "$SERVER_PID" >/dev/null 2>&1; then
		kill "$SERVER_PID" >/dev/null 2>&1 || true
		sleep 0.2
		if ps -p "$SERVER_PID" >/dev/null 2>&1; then kill -9 "$SERVER_PID" >/dev/null 2>&1 || true; fi
	fi
	if [ -n "${TAIL_PID:-}" ] && ps -p "$TAIL_PID" >/dev/null 2>&1; then kill "$TAIL_PID" >/dev/null 2>&1 || true; fi
	wait "$SERVER_PID" 2>/dev/null || true
	exit 0
}
on_exit(){
	command -v stty >/dev/null 2>&1 && [ -t 0 ] && stty echo
	printf '%b\n' "${DONE_COLOR} completed."
	line "THANKS FOR USING TERMUXCONF"
	printf '\n'
}
trap cleanup INT TERM
trap on_exit EXIT

sleep 0.3
if ps -p "$SERVER_PID" >/dev/null 2>&1; then
	printf '%b\n' "${DONE_COLOR} server started (pid=${SERVER_PID}), logs: ${LOG}"
else
	printf '%b\n' "${ERR_COLOR} server failed to start, check ${LOG}"
	cat "$LOG"
	wait "$SERVER_PID" 2>/dev/null || true
	exit 1
fi
sleep 1
if command -v termux-open-url >/dev/null 2>&1; then
	printf '%b\n' "${INFO_COLOR} starting browser..."
	termux-open-url "http://$ADDRESS:$PORT/" 2>/dev/null
else
	printf '\n%b\n' "${INFO_COLOR} open this URL in your browser: http://$ADDRESS:$PORT/"
fi
wait "$SERVER_PID"
